import Foundation
import UIKit

/// In-memory backend with a real sample of museum works (DemoLibrary.json,
/// generated by the server's importer). Lets the app be explored before a
/// frame server exists. Images come from Resources/DemoImages (originals and
/// their e-paper look rendered by the server pipeline, framed on the phone by
/// DemoFraming), falling back to the museums' CDNs.
actor DemoBackend: FrameBackend {
    nonisolated var isDemo: Bool { true }

    private struct DemoFile: Decodable {
        let items: [Item]
        let playlists: [Playlist]
        /// Crops the server's interest analysis chose: item id -> orientation -> crops.
        var framing: [String: [String: DemoFraming.Crops]]?
        /// The "picture" mat the server picks for each work (#rrggbb, screen colours).
        var tints: [String: String]?
        /// And the "picture_dark" one.
        var darkTints: [String: String]?
    }

    private var items: [Item]
    private var playlistsByID: [Int: Playlist]
    private var settingsValue = FrameSettings.defaults
    private var queue: [String] = []
    /// Added with "Dodaj do kolejki": at the front of `queue`.
    private var queued: [String] = []
    private var history: [String] = []
    private var currentID: String?
    private var holdValue: Hold?
    private static let demoPanel = PanelConfig(host: "192.168.1.50", mac: nil, port: 1515, pinSet: true, fromApp: false)
    private var panelValue = DemoBackend.demoPanel
    private var catalogueLimitMb: Int?
    /// "Aktualizuj serwer" in demo: the newer version is installed at once.
    private var demoServerVersion = "0.35.0"
    private var originalsLimitMb: Int?
    /// Studies asked for, and when: "written" a few seconds later.
    private var askedStudies: [String: Date] = [:]
    private var aiValue = AiSettings(
        keySet: false, keyTail: nil, keyFromApp: false, plText: true, keywordsArtworks: true,
        keywordsPhotos: true, daily: true, monthlyLimitUsd: 5, spentUsd: 0,
        keywordsProgress: .init(done: 0, waiting: 0, refused: 0, batchItems: 0, batchDone: 0, preparing: false),
        plTextProgress: nil, error: nil
    )
    private var demoAsleep = false
    /// The picture "on its way" to the pretend frame, for the progress bar.
    private var run: (title: String, start: Date)?
    /// Demo stages: 14 s in all, where a real panel takes about a minute.
    private static let runStages: [(stage: String, phase: String, seconds: Double)] = [
        ("rendering", "processing", 2.5), ("sending", "loading", 1), ("downloading", "loading", 1.5),
        ("refreshing", "displaying", 9),
    ]
    private var demoJobs: [String: JobStatus] = [:]
    private struct ImageURLs: Sendable {
        let thumb: URL?
        let image: URL?
    }

    private let imageURLs: [String: ImageURLs]
    /// Remote museum URL -> item id, so search results also use bundled files.
    private let idsByURL: [URL: String]
    private let arts: [String: DemoFraming.Art]
    private let autoCrops: [String: [String: DemoFraming.Crops]]
    /// Settings and crop corrections as last saved, for nonisolated image requests.
    private let shared = FramingState()
    private var framingRevision = 0

    init() {
        let loaded = Self.load()
        items = loaded.items
        var byID: [Int: Playlist] = [:]
        for (index, playlist) in loaded.playlists.enumerated() {
            var copy = playlist
            copy.id = index + 1
            byID[index + 1] = copy
        }
        playlistsByID = byID
        imageURLs = Dictionary(
            uniqueKeysWithValues: loaded.items.map {
                ($0.id, ImageURLs(thumb: URL(string: $0.thumbUrl), image: URL(string: $0.imageUrl)))
            }
        )
        var byURL: [URL: String] = [:]
        for (id, urls) in imageURLs {
            for url in [urls.thumb, urls.image].compactMap({ $0 }) { byURL[url] = id }
        }
        idsByURL = byURL
        arts = Dictionary(
            uniqueKeysWithValues: loaded.items.map {
                ($0.id, DemoFraming.Art(
                    caption: DemoFraming.caption(for: $0), text: DemoFraming.textBlock(for: $0),
                    isPhoto: $0.kind == .photo, tint: loaded.tints?[$0.id].flatMap(DemoFraming.color(hex:)),
                    darkTint: loaded.darkTints?[$0.id].flatMap(DemoFraming.color(hex:))
                ))
            }
        )
        autoCrops = loaded.framing ?? [:]
        // Start out playing the first playlist, like a fresh server does.
        settingsValue.playlistId = 1
        settingsValue.art.fit = "description"  // shows off the work's text and detail
        if let fit = LaunchRoute.fit { settingsValue.art.fit = fit }
        if let mat = LaunchRoute.mat { settingsValue.art.mat = mat }
        let first = byID[1].map { playlist in
            Self.sorted(loaded.items.filter { Self.matches($0, playlist.rules) }, by: "suitability")
        }
        queue = (first.flatMap { $0.isEmpty ? nil : $0 } ?? loaded.items).map(\.id)
        currentID = queue.first
        if !queue.isEmpty { queue.removeFirst() }
        if ["history", "history-back"].contains(LaunchRoute.screen) {
            // CI screenshots: "Ostatnio na ramce" with pictures in it.
            let earlier = loaded.items.map(\.id).filter { $0 != currentID && !queue.prefix(8).contains($0) }
            history = Array(earlier.prefix(4).reversed())
        }
        shared.current = settingsValue
        shared.shown = settingsValue
    }

    private static func load() -> DemoFile {
        guard
            let url = Bundle.main.url(forResource: "DemoLibrary", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let file = try? LiveBackend.decoder().decode(DemoFile.self, from: data)
        else { return DemoFile(items: [], playlists: [], framing: nil, tints: nil) }
        return file
    }

    // MARK: Matching (mirrors server/src/frame_server/library/repo.py)

    /// `listed`: the works on the playlists, for "Moje: Playlisty".
    private static func matches(_ item: Item, _ rules: PlaylistRules, listed: Set<String> = []) -> Bool {
        if item.excluded || item.look != nil || rules.excludeIds.contains(item.id) { return false }
        if rules.favoritesOnly && !item.favorite { return false }
        let mine = rules.terms.filter { MineTerm.named($0) != nil }
        if !mine.isEmpty,
           !(mine.contains(MineTerm.favorites.key) && item.favorite),
           !(mine.contains(MineTerm.playlists.key) && listed.contains(item.id)) {
            return false
        }
        if !rules.kinds.isEmpty && !rules.kinds.contains(item.kind) { return false }
        if !rules.sources.isEmpty && !rules.sources.contains(item.source) { return false }
        if !rules.artists.isEmpty && !DemoDiscover.artistMatches(item.artist, rules.artists) { return false }
        func overlaps(_ a: [String], _ b: [String]) -> Bool {
            Set(a.map { $0.lowercased() }).intersection(b.map { $0.lowercased() }).isEmpty == false
        }
        if !rules.styles.isEmpty && !overlaps(item.styles, rules.styles) { return false }
        if !rules.subjects.isEmpty && !overlaps(item.subjects, rules.subjects) { return false }
        // As the server: colours and moods one group, accents another, both must fit.
        let accents = rules.colors.filter { $0.hasPrefix(ColorTag.accentPrefix) }
        let mainColors = rules.colors.filter { !$0.hasPrefix(ColorTag.accentPrefix) }
        if !mainColors.isEmpty && Set(item.colorTags).isDisjoint(with: mainColors) { return false }
        if !accents.isEmpty && Set(item.colorTags).isDisjoint(with: accents) { return false }
        if !rules.terms.isEmpty && !DemoDiscover.matches(item, terms: rules.terms) { return false }
        if let from = rules.yearFrom, (item.year ?? Int.min) < from { return false }
        if let to = rules.yearTo, (item.year ?? Int.max) > to { return false }
        if !rules.query.isEmpty {
            let haystack = ([item.title, item.artist, item.medium, item.classification, item.culture]
                + item.styles + item.subjects).joined(separator: " ").lowercased()
            for word in rules.query.lowercased().split(separator: " ") where !haystack.contains(word) {
                return false
            }
        }
        return true
    }

    private static func sorted(_ list: [Item], by sort: String) -> [Item] {
        switch sort {
        case "title": list.sorted { $0.title < $1.title }
        case "year": list.sorted { ($0.year ?? 0) < ($1.year ?? 0) }
        case "recent": list.sorted { $0.addedAt > $1.addedAt }
        case "suitability": list.sorted { ($0.suitability ?? 0) > ($1.suitability ?? 0) }
        default: list.sorted { ($0.artist, $0.year ?? 0) < ($1.artist, $1.year ?? 0) }
        }
    }

    private func items(for playlist: Playlist) -> [Item] {
        if playlist.kind != .smart {
            return playlist.itemIds
                .filter { !playlist.rules.excludeIds.contains($0) }
                .compactMap { id in items.first { $0.id == id } }
        }
        let listed = listed(for: playlist.rules)
        let found = Self.sorted(items.filter { Self.matches($0, playlist.rules, listed: listed) }, by: "suitability")
        guard let limit = playlist.limit, found.count > limit else { return found }
        // As the server: favourites first, then a steady draw.
        let taken = Set(found.sorted { ($0.favorite ? 0 : 1, $0.id.hashValue) < ($1.favorite ? 0 : 1, $1.id.hashValue) }
            .prefix(limit).map(\.id))
        return found.filter { taken.contains($0.id) }
    }

    /// The works on the playlists but "Ulubione", when `rules` ask for them
    /// (smart playlists asking for them too left out).
    private func listed(for rules: PlaylistRules) -> Set<String> {
        guard rules.terms.contains(MineTerm.playlists.key) else { return [] }
        let others = playlistsByID.values.filter { playlist in
            !playlist.isFavorites && !(playlist.kind == .smart && playlist.rules.terms.contains(MineTerm.playlists.key))
        }
        return Set(others.flatMap { items(for: $0).map(\.id) })
    }

    private func summary(_ playlist: Playlist) -> PlaylistSummary {
        let list = items(for: playlist)
        return PlaylistSummary(
            id: playlist.id ?? 0, name: playlist.name, description: playlist.description,
            kind: playlist.kind, rules: playlist.rules, itemCount: list.count,
            coverItemIds: list.prefix(4).map(\.id),
            coverColors: list.prefix(4).compactMap { $0.colors.max { $0.weight < $1.weight } },
            album: playlist.album,
            albumSync: playlist.album.map { _ in
                AlbumSync(
                    at: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-1800)),
                    name: playlist.name, count: list.count
                )
            },
            theme: playlist.theme, limit: playlist.limit
        )
    }

    private func detail(_ playlist: Playlist) -> PlaylistDetail {
        PlaylistDetail(
            playlist: summary(playlist), itemIds: playlist.itemIds,
            items: items(for: playlist).map(\.summary)
        )
    }

