    func player() async throws -> PlayerView {
        let current = currentID.flatMap { id in items.first { $0.id == id } }
        let playlist = settingsValue.playlistId.flatMap { playlistsByID[$0] }.map(summary)
        let nowShowing = current.map {
            NowShowing(
                title: $0.title, description: "\($0.artist) — \($0.title)", source: $0.source,
                created: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-5400)),
                previewUrl: "/demo/\($0.id)?\(shared.shown.presentationKey)|\(framingRevision)", item: $0
            )
        }
        let next = settingsValue.changeTimes.compactMap { time -> Date? in
            let parts = time.split(separator: ":").compactMap { Int($0) }
            guard parts.count == 2 else { return nil }
            return Calendar.current.nextDate(
                after: .now, matching: DateComponents(hour: parts[0], minute: parts[1]), matchingPolicy: .nextTime
            )
        }.min()
        return PlayerView(
            playlist: playlist, current: nowShowing,
            upcoming: queue.prefix(8).compactMap { id in items.first { $0.id == id }?.summary },
            queued: queued,
            history: history.suffix(8).reversed().compactMap { id in items.first { $0.id == id }?.summary },
            hold: holdValue,
            lastChangeAt: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-5400)),
            nextChangeAt: next.map { ISO8601DateFormatter().string(from: $0) },
            busy: runElapsed.map { $0 < 5 } ?? false, lastError: nil, progress: try await progress(),
            historyMarks: demoMarks()
        )
    }

    /// Who put the pictures of "Ostatnio na ramce" there: the schedule at
    /// 7:00 and 19:30, and one sent from the app in between.
    private func demoMarks() -> [String: ShownMark] {
        let ids = Array(history.suffix(8).reversed())
        var marks: [String: ShownMark] = [:]
        for (index, id) in ids.enumerated() {
            let fromApp = index % 3 == 1
            let hours = 5400.0 / 3600 + Double(index) * 6 + (fromApp ? 3 : 0)
            marks[id] = ShownMark(
                at: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-hours * 3600)),
                origin: fromApp ? "app" : "schedule"
            )
        }
        return marks
    }

    private var runElapsed: Double? { run.map { Date.now.timeIntervalSince($0.start) } }

    /// A picture on its way to the frame: drawn with the settings as they are now.
    private func startRun(_ title: String) {
        run = (title: title, start: Date.now)
        shared.shown = settingsValue
    }

    private func startRun(itemID: String?) {
        startRun(items.first { $0.id == itemID }?.title ?? "")
    }

    func progress() async throws -> DisplayProgress {
        guard let run, let elapsed = runElapsed else { return .idle }
        let stamp = ISO8601DateFormatter().string(from: run.start)
        let total = Self.runStages.reduce(0) { $0 + $1.seconds }
        var end = 0.0
        for step in Self.runStages {
            end += step.seconds
            if elapsed < end {
                return DisplayProgress(
                    stage: step.stage, phase: step.phase, active: true, title: run.title,
                    fraction: elapsed / total, secondsLeft: Int((total - elapsed).rounded(.up)),
                    startedAt: stamp, origin: "app"
                )
            }
        }
        return DisplayProgress(
            stage: "done", active: false, title: run.title, fraction: 1, startedAt: stamp,
            finishedAt: ISO8601DateFormatter().string(from: run.start.addingTimeInterval(total))
        )
    }

    func next() async throws {
        guard !queue.isEmpty else { return }
        if let currentID { history.append(currentID) }
        currentID = queue.removeFirst()
        queued.removeAll { $0 == currentID }
        holdValue = nil
        startRun(itemID: currentID)
    }

    func previous() async throws {
        guard let previous = history.popLast() else { return }
        if let currentID { queue.insert(currentID, at: 0) }
        currentID = previous
        holdValue = nil
        startRun(itemID: currentID)
    }

    func hold(_ spec: HoldSpec) async throws -> PlayerView {
        switch spec {
        case .untilNextChange: holdValue = nil
        case .forever: holdValue = Hold(until: nil, forever: true)
        default:
            let minutes = Double(spec.wireValue) ?? 60
            holdValue = Hold(
                until: ISO8601DateFormatter().string(from: .now.addingTimeInterval(minutes * 60)),
                forever: false
            )
        }
        return try await player()
    }

    func releaseHold() async throws -> PlayerView {
        holdValue = nil
        return try await player()
    }

    // MARK: Library

    func items(_ query: LibraryQuery) async throws -> ItemPage {
        let rules = PlaylistRules(
            query: query.text, artists: query.artists, styles: query.styles, subjects: query.subjects,
            terms: query.terms, colors: query.colors, kinds: query.kinds, sources: query.sources,
            yearFrom: query.yearFrom,
            yearTo: query.yearTo, favoritesOnly: query.favoritesOnly
        )
        let listed = listed(for: rules)
        let list = Self.sorted(items.filter { Self.matches($0, rules, listed: listed) }, by: query.sort)
        let page = list.dropFirst(query.offset).prefix(query.limit)
        return ItemPage(total: list.count, items: page.map(\.summary))
    }

    func item(id: String) async throws -> Item {
        guard let item = items.first(where: { $0.id == id }) else { throw BackendError.notFound }
        return item
    }

    /// A long note, as the language model writes one (400–900 characters),
    /// so the card shows "O dziele" in full in the demo screenshots.
    func polish(itemID: String, wait: Int) async throws -> PolishView {
        guard let item = items.first(where: { $0.id == itemID }) else { return PolishView(status: "off", text: nil) }
        let note = """
        Pierwszy plan zajmuje stół przykryty białym obrusem, na którym stoją kosz z owocami, \
        ciemna butelka i talerz z podłużnymi ciastkami. Obrus układa się w ostre, geometryczne \
        płaszczyzny, w których biel łączy się z błękitem i szarością. Owoce są modelowane osobnymi \
        plamami czerwieni, zieleni, żółci i pomarańczu, bez gładkich przejść. Perspektywa nie jest \
        jednolita: blat stołu zdaje się unosić ku górze, a kosz po lewej jest pochylony, jakby każdy \
        przedmiot oglądano z innego miejsca. W lewym dolnym rogu fałdy obrusu opadają ku krawędzi \
        stołu i zamykają kompozycję.

        Tło jest spokojne i ciepłe, z brązami i ochrą położonymi szerokimi pociągnięciami pędzla. \
        Dzięki temu jasne owoce i biel tkaniny wysuwają się do przodu, a cała scena nabiera ciężaru. \
        To ostatnie zdanie notki kończy się tutaj.
        """
        let text = PolishText(
            title: item.title, frame: note, full: note, medium: item.medium, date: item.dateText,
            artistNote: item.artistBio, written: "note", sources: ["dane muzeum", "obraz"]
        )
        return PolishView(status: "ready", text: text)
    }

    func describe(itemID: String, wait: Int) async throws -> SeenView {
        SeenView(status: "off", words: [])
    }

    private func update(_ id: String, _ change: (inout Item) -> Void) throws -> Item {
        guard let index = items.firstIndex(where: { $0.id == id }) else { throw BackendError.notFound }
        change(&items[index])
        return items[index]
    }

    func setFavorite(id: String, _ favorite: Bool) async throws -> Item {
        try update(id) { $0.favorite = favorite }
    }

    func setExcluded(id: String, _ excluded: Bool) async throws -> Item {
        try update(id) { $0.excluded = excluded }
    }

    func show(itemID: String, hold: HoldSpec) async throws {
        if let currentID { history.append(currentID) }
        currentID = itemID
        queue.removeAll { $0 == itemID }
        queued.removeAll { $0 == itemID }
        _ = try await self.hold(hold)
        startRun(itemID: itemID)
    }

    func queueNext(itemID: String) async throws {
        guard items.contains(where: { $0.id == itemID }) else { throw BackendError.notFound }
        queue.removeAll { $0 == itemID }
        queue.insert(itemID, at: 0)
        queued.removeAll { $0 == itemID }
        queued.insert(itemID, at: 0)
    }

    func dequeue(itemID: String) async throws -> PlayerView {
        if queued.contains(itemID) {
            queued.removeAll { $0 == itemID }
            queue.removeAll { $0 == itemID }
        }
        return try await player()
    }

    func skip(itemID: String) async throws -> PlayerView {
        if queued.contains(itemID) {
            queued.removeAll { $0 == itemID }
            queue.removeAll { $0 == itemID }
        } else if queue.contains(itemID) {
            queue.removeAll { $0 == itemID }
            queue.append(itemID)  // after the rest of the round
        }
        return try await player()
    }

    // MARK: Framing

    func framing(itemID: String, orientation: String, automatic: Bool) async throws -> FramingView {
        guard let item = items.first(where: { $0.id == itemID }),
              let size = DemoFraming.pixelSize(itemID)
        else { throw BackendError.notFound }
        let pres = item.look.map { settingsValue.photo.with($0) } ?? (item.kind == .photo ? settingsValue.photo : settingsValue.art)
        let custom = automatic ? nil : shared.crops[itemID]?[orientation]
        let canvas = DemoFraming.canvas(orientation)
        let plan = DemoFraming.plan(
            size, canvas: canvas, presentation: pres, caption: pres.label,
            crops: automatic ? autoCrops[itemID]?[orientation].map { FramingCrops(fill: $0.fill, detail: $0.detail) }
                : crops(itemID, orientation)
        )
        let area = plan.fit == "fit"
            ? Self.unit(DemoFraming.fitArea(canvas, margin: pres.margin, caption: pres.label), canvas) : nil
        let isCustom = switch plan.fit {
        case "fill": custom?.fill != nil
        case "description": custom?.detail != nil || custom?.picture != nil
        case "fit": custom?.fit != nil
        default: false
        }
        let windows = plan.windows.compactMap { window -> FramingWindow? in
            guard let crop = window.crop else { return nil }
            return FramingWindow(
                role: window.role, aspect: window.rect.width / window.rect.height, crop: crop, custom: isCustom,
                rect: Self.unit(window.rect, canvas), area: window.role == "picture" ? area : nil
            )
        }
        return FramingView(orientation: orientation, fit: plan.fit, width: Int(size.width), height: Int(size.height), windows: windows)
    }

    /// A rect on the canvas as fractions of it, as the server sends it.
    private static func unit(_ rect: CGRect, _ canvas: CGSize) -> [Double] {
        [rect.minX / canvas.width, rect.minY / canvas.height, rect.width / canvas.width, rect.height / canvas.height]
    }

    func saveFraming(itemID: String, orientation: String, crops: [Crop]) async throws -> FramingView {
        let current = try await framing(itemID: itemID, orientation: orientation)
        var saved = shared.crops[itemID]?[orientation] ?? DemoFraming.Crops()
        switch (current.fit, crops.count) {
        case ("fill", 1): saved.fill = crops[0]
        case ("description", 2):
            saved.picture = crops[0] == DemoFraming.wholeCrop ? nil : crops[0]
            saved.detail = crops[1]
        case ("description", 1): saved.detail = crops[0]
        case ("fit", 1): saved.fit = crops[0]
        default: throw BackendError.http(status: 422, body: "")
        }
        shared.crops[itemID, default: [:]][orientation] = saved
        framingRevision += 1
        if itemID == currentID { startRun(itemID: itemID) }
        return try await framing(itemID: itemID, orientation: orientation)
    }

    func resetFraming(itemID: String, orientation: String) async throws -> FramingView {
        // Only the current mode's crop goes back to automatic.
        let current = try await framing(itemID: itemID, orientation: orientation)
        var saved = shared.crops[itemID]?[orientation] ?? DemoFraming.Crops()
        switch current.fit {
        case "fill": saved.fill = nil
        case "description":
            saved.detail = nil
            saved.picture = nil
        default: saved.fit = nil
        }
        shared.crops[itemID, default: [:]][orientation] = saved
        framingRevision += 1
        if itemID == currentID { startRun(itemID: itemID) }
        return try await framing(itemID: itemID, orientation: orientation)
    }

    /// The user's correction, else what the server's analysis chose.
    private nonisolated func crops(_ id: String, _ orientation: String) -> DemoFraming.Crops? {
        let auto = autoCrops[id]?[orientation]
        guard let custom = shared.crops[id]?[orientation] else { return auto }
        return DemoFraming.Crops(
            fill: custom.fill ?? auto?.fill, detail: custom.detail ?? auto?.detail,
            picture: custom.picture, fit: custom.fit
        )
    }

    func facets() async throws -> Facets {
        func top(_ values: [String]) -> [FacetValue] {
            Dictionary(values.map { ($0, 1) }, uniquingKeysWith: +)
                .filter { !$0.key.isEmpty }
                .map { FacetValue(value: $0.key, count: $0.value) }
                .sorted { ($0.count, $1.value) > ($1.count, $0.value) }
        }
        let visible = items.filter { !$0.excluded }
        return Facets(
            artists: top(visible.map(\.artist)),
            styles: top(visible.flatMap(\.styles)),
            subjects: top(visible.flatMap(\.subjects)),
            colors: top(visible.flatMap(\.colorTags)),
            sources: top(visible.map(\.source)),
            kinds: top(visible.map(\.kind.rawValue))
        )
    }

    // MARK: Playlists

    func playlists() async throws -> [PlaylistSummary] {
        playlistsByID.keys.sorted().compactMap { playlistsByID[$0] }.map(summary)
    }

    func playlist(id: Int) async throws -> PlaylistDetail {
        guard let playlist = playlistsByID[id] else { throw BackendError.notFound }
        return detail(playlist)
    }

    func savePlaylist(_ playlist: Playlist) async throws -> PlaylistDetail {
        var copy = playlist
        if copy.id == nil { copy.id = (playlistsByID.keys.max() ?? 0) + 1 }
        playlistsByID[copy.id!] = copy
        return detail(copy)
    }

    func deletePlaylist(id: Int) async throws {
        // As the server: "Ulubione" stays.
        if playlistsByID[id]?.isFavorites == true { throw BackendError.http(status: 409, body: "Ulubione zostają zawsze") }
        playlistsByID[id] = nil
    }

    func addToPlaylist(id: Int, itemIDs: [String]) async throws -> PlaylistDetail {
        guard var playlist = playlistsByID[id] else { throw BackendError.notFound }
        playlist.itemIds += itemIDs.filter { !playlist.itemIds.contains($0) }
        playlistsByID[id] = playlist
        return detail(playlist)
    }

    func removeFromPlaylist(id: Int, itemID: String) async throws -> PlaylistDetail {
        guard var playlist = playlistsByID[id] else { throw BackendError.notFound }
        if playlist.kind == .manual {
            playlist.itemIds.removeAll { $0 == itemID }
        } else if !playlist.rules.excludeIds.contains(itemID) {
            playlist.rules.excludeIds.append(itemID)
        }
        playlistsByID[id] = playlist
        if settingsValue.playlistId == id { queue.removeAll { $0 == itemID } }
        return detail(playlist)
    }

    func previewRules(_ rules: PlaylistRules) async throws -> RulesPreview {
        let list = Self.sorted(items.filter { Self.matches($0, rules) }, by: "suitability")
        return RulesPreview(count: list.count, items: list.prefix(24).map(\.summary))
    }

    func play(playlistID: Int) async throws {
        guard let playlist = playlistsByID[playlistID] else { throw BackendError.notFound }
        settingsValue.playlistId = playlistID
        queue = items(for: playlist).map(\.id).shuffled()
        try await next()
    }

    func playSuggestions() async throws {
        settingsValue.playlistId = nil
        queue = items.map(\.id).shuffled()
        try await next()
    }

    // MARK: Settings, museums, device

    func settings() async throws -> FrameSettings { settingsValue }

    func saveSettings(_ settings: FrameSettings) async throws -> FrameSettings {
        // As the server: only a turned screen redraws the picture on the
        // frame; a new presentation waits for the next one.
        let turned = settings.screenKey != settingsValue.screenKey
        settingsValue = settings
        shared.current = settings
        if turned { startRun(itemID: currentID) }
        return settings
    }

