    func study(itemID: String, wait: Int) async throws -> StudyView {
        guard let asked = askedStudies[itemID] else {
            return StudyView(status: "none", error: "", work: nil, costUsd: 0.14)
        }
        let elapsed = Date().timeIntervalSince(asked)
        if elapsed < 6 {
            try? await Task.sleep(for: .seconds(min(Double(wait), 2)))
            return StudyView(status: elapsed < 2 ? "sources" : "writing", error: "", work: nil, costUsd: 0.14)
        }
        guard let item = items.first(where: { $0.id == itemID }) else { throw BackendError.notFound }
        var work = try await daily(day: nil, wait: 0)
        work.day = ""
        work.whyToday = ""
        if work.item.id != itemID {
            // The demo's text is about the wave: another work keeps what its museum says.
            work.item = RemoteItem(item: item, inLibrary: true)
            work.title = item.title
            work.teaser = ""
            work.headline = "Co mówi muzeum"
            work.context = item.description.isEmpty ? [] : [item.description]
            work.artist = item.artistBio
            work.composition = nil
            work.colour = ""
            work.details = []
            work.onFrame = ""
            work.legacy = []
            work.similar = []
            work.byArtist = byArtist(item, skip: [])
        }
        return StudyView(status: "ready", error: "", work: work, costUsd: 0.14)
    }

    /// Up to six other works by `item`'s artist ("Inne prace artysty").
    private func byArtist(_ item: Item, skip: Set<String>) -> [RemoteItem] {
        guard !item.artist.isEmpty else { return [] }
        return items
            .filter { $0.id != item.id && !skip.contains($0.id) && $0.artist == item.artist }
            .prefix(6)
            .map { RemoteItem(item: $0, inLibrary: true) }
    }

    /// The ones asked for (the last first), then a few the demo has written;
    /// the wave is today's work of the day and opens as that.
    func studies() async throws -> [StudyBrief] {
        let asked = askedStudies.filter { Date().timeIntervalSince($0.value) >= 6 }.sorted { $0.value > $1.value }.map { $0.key }
        let ids = asked + ["aic:24645", "aic:14620", "aic:64818", "aic:87008", "aic:2914"].filter { !asked.contains($0) }
        let parts = Calendar.current.dateComponents([.year, .month, .day], from: Date())
        let today = String(format: "%04d-%02d-%02d", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
        return ids.compactMap { id in
            items.first { $0.id == id }.map {
                StudyBrief(
                    item: RemoteItem(item: $0, inLibrary: true),
                    title: $0.title,
                    day: id == "aic:24645" && !asked.contains(id) ? today : nil
                )
            }
        }
    }

