    // MARK: Images

    nonisolated func request(for image: ImageRef) -> URLRequest? {
        let url: URL?
        switch image {
        case let .thumb(id): url = Self.bundled(id) ?? imageURLs[id]?.thumb
        case let .image(id): url = Self.bundled(id) ?? imageURLs[id]?.image ?? imageURLs[id]?.thumb
        case let .framePreview(id, settings, framing, _):
            url = framed(id, settings, trying: framing) ?? Self.bundled(id) ?? imageURLs[id]?.thumb
        case let .path(path) where path.hasPrefix("/demo/detail/"):
            url = Self.detail(path)
        case let .path(path):
            // "/demo/<id>?<presentation key>"; the key only makes the path change.
            let id = String(path.dropFirst("/demo/".count).prefix { $0 != "?" })
            url = framed(id, shared.shown) ?? Self.bundled(id) ?? imageURLs[id]?.image
        case let .url(remote): url = idsByURL[remote].flatMap { Self.bundled($0) } ?? remote
        }
        return url.map { URLRequest(url: $0, timeoutInterval: 60) }
    }

    private nonisolated func framed(_ id: String, _ settings: FrameSettings? = nil, trying: FramingCrops? = nil) -> URL? {
        let settings = settings ?? shared.current
        var chosen = crops(id, settings.orientation)
        if let trying {  // as the server: the crops given replace the saved ones
            let saved = chosen ?? FramingCrops()
            chosen = FramingCrops(
                fill: trying.fill ?? saved.fill, detail: trying.detail ?? saved.detail,
                picture: trying.picture ?? saved.picture, fit: trying.fit ?? saved.fit
            )
        }
        return (arts[id] ?? shared.uploads[id]).flatMap {
            DemoFraming.framed(id, art: $0, settings: settings, crops: chosen)
        }
    }

    /// Resources/DemoImages/<stem>.jpg
    /// "/demo/detail/<id>?x=&y=&w=&h=": a fragment of the work of the day,
    /// cut from the bundled picture as the server cuts it from the original.
    private static func detail(_ path: String) -> URL? {
        guard let parts = URLComponents(string: path) else { return nil }
        let id = String(parts.path.dropFirst("/demo/detail/".count))
        func value(_ name: String) -> Double { Double(parts.queryItems?.first { $0.name == name }?.value ?? "") ?? 0 }
        let out = FileManager.default.temporaryDirectory
            .appendingPathComponent("demo-detail-\(DemoFraming.stem(id))-\(value("x"))-\(value("y")).jpg")
        if FileManager.default.fileExists(atPath: out.path) { return out }
        guard let source = bundled(id), let image = UIImage(contentsOfFile: source.path)?.cgImage else { return nil }
        let width = Double(image.width), height = Double(image.height)
        let box = CGRect(x: value("x") * width, y: value("y") * height, width: value("w") * width, height: value("h") * height)
        guard let cut = image.cropping(to: box.integral),
              let data = UIImage(cgImage: cut).jpegData(compressionQuality: 0.9)
        else { return nil }
        try? data.write(to: out)
        return out
    }

    private static func bundled(_ id: String) -> URL? {
        if let url = Bundle.main.url(forResource: DemoFraming.stem(id), withExtension: "jpg") { return url }
        let upload = DemoFraming.uploadURL(id)
        return FileManager.default.fileExists(atPath: upload.path) ? upload : nil
    }
}

/// Lock-guarded settings and crop corrections for image requests, which run
/// outside the actor.
private final class FramingState: @unchecked Sendable {
    private let lock = NSLock()
    private var value = FrameSettings.defaults
    private var shownValue = FrameSettings.defaults
    private var corrections: [String: [String: DemoFraming.Crops]] = [:]

    var current: FrameSettings {
        get { lock.withLock { value } }
        set { lock.withLock { value = newValue } }
    }

    /// The settings the picture on the frame was drawn with.
    var shown: FrameSettings {
        get { lock.withLock { shownValue } }
        set { lock.withLock { shownValue = newValue } }
    }

    /// Item id -> orientation -> the user's crops.
    var crops: [String: [String: DemoFraming.Crops]] {
        get { lock.withLock { corrections } }
        set { lock.withLock { corrections = newValue } }
    }

    private var uploaded: [String: DemoFraming.Art] = [:]

    /// Photos "uploaded" in this demo session.
    var uploads: [String: DemoFraming.Art] {
        get { lock.withLock { uploaded } }
        set { lock.withLock { uploaded = newValue } }
    }
}
